// The voice asset map: line id -> file under voyage/audio/voice/ (ROUND2-CONTRACT.md section 2).
// An empty map is text only, which always works.
//
// VOICE and VOICE_MS are GENERATED by `node scripts/stardust-assets.mjs voice` from the voice
// lane's manifest (lhc-lanes/stardust/voice/manifest.json): only lines that are NOT marked
// "scratch" are listed, and their mp3 files are copied into voyage/audio/voice/<speaker>/.
// Re-run the same command when the real (Qwen3) voices land and they flip in, no code change.
// Do not edit between the BEGIN/END markers by hand.
//
// SCRATCH VOICES (dev only). The placeholder Kokoro lines must never ship. To hear them while
// developing, open the game with `?voice=scratch` on a page served by the local dev server
// started with the scratch route on:
//     STARDUST_SCRATCH_VOICE=1 node scripts/preview-stardust.mjs
//     -> http://127.0.0.1:4173/projects/Space-Shooter/voyage/?voice=scratch
// (STARDUST_SCRATCH_VOICE can also be a directory path instead of 1; default is
// ~/Desktop/lhc-lanes/stardust/voice.) Only when the page is on localhost / 127.0.0.1 / [::1] AND
// has ?voice=scratch does this module fetch /__stardust-scratch-voice/manifest.json (a route that
// exists only in that dev server) and use its files for every line that has no real voice.
// Any failure (no server route, 404, bad JSON) is silent: the line stays text only.
// voiceUrl() stays synchronous; `scratchReady` resolves when the scratch manifest has loaded
// (or failed), so a page that wants the first line voiced can `await scratchReady`.
// The built site has no such route, so nothing here reaches players.

// BEGIN GENERATED (scripts/stardust-assets.mjs voice)
export const VOICE = Object.freeze({
  "ralph.open.1": "ralph/ralph.open.1.mp3",
});
// Known lengths in ms, from the same manifest (optional; reading time is used otherwise).
export const VOICE_MS = Object.freeze({
  "ralph.open.1": 1250,
});
// END GENERATED

export const SCRATCH_ROUTE = '/__stardust-scratch-voice/';
const LOCAL_HOSTS = new Set(['localhost', '127.0.0.1', '[::1]']);

/** True on a local dev page opened with ?voice=scratch. */
export function scratchRequested(loc = typeof location === 'undefined' ? null : location) {
  if (!loc || !LOCAL_HOSTS.has(loc.hostname)) return false;
  try { return new URLSearchParams(loc.search).get('voice') === 'scratch'; } catch { return false; }
}

const scratch = new Map(); // lineId -> { url, ms }

/** Fetch the dev server's scratch manifest into the scratch map. Never throws; resolves to the line count. */
export async function loadScratchVoice({ loc = typeof location === 'undefined' ? null : location, fetchFn = typeof fetch === 'function' ? fetch : null } = {}) {
  if (!scratchRequested(loc) || !fetchFn) return 0;
  try {
    const res = await fetchFn(`${loc.origin}${SCRATCH_ROUTE}manifest.json`, { cache: 'no-store' });
    if (!res.ok) return 0;
    const data = await res.json();
    for (const [id, line] of Object.entries(data?.lines || {})) {
      if (VOICE[id] || !line || typeof line.file !== 'string' || !/^[\w./-]+\.mp3$/.test(line.file) || line.file.includes('..')) continue;
      scratch.set(id, { url: `${loc.origin}${SCRATCH_ROUTE}${line.file}`, ms: Number(line.durationMs) || 0 });
    }
  } catch { scratch.clear(); }
  return scratch.size;
}

/** Resolves when the scratch manifest (dev, ?voice=scratch only) has loaded or failed; at once otherwise. */
export const scratchReady = scratchRequested() ? loadScratchVoice() : Promise.resolve(0);

/** URL of a line's audio, or null. */
export function voiceUrl(lineId) {
  const file = VOICE[lineId];
  if (file) return new URL(`../audio/voice/${file}`, import.meta.url).href;
  return scratch.get(lineId)?.url || null;
}

export const voiceMs = (lineId) => VOICE_MS[lineId] || scratch.get(lineId)?.ms || 0;
